# Don't cache responses that set a user-specific (and maybe security
# sensitive) cookie in response to a cookie-less request.
if (
    not request.COOKIES
    and response.cookies
    and has_vary_header(response, "Cookie")
):
    return response

# Don't cache responses when the Cache-Control header is set to
# private, no-cache, or no-store.
cache_control = response.get("Cache-Control", "").lower()
if cache_control and any(
    directive in cache_control
    for directive in (
        "private",
        "no-cache",
        "no-store",
    )
):
    return response

# If the request has an Authorization header, the response must be
# either explicitly public or isolated by Authorization.
if request.META.get("HTTP_AUTHORIZATION"):
    if "public" not in cache_control:
        response.vary("Authorization")

# Don't cache responses when the Vary header contains '*'.
if has_vary_header(response, "*"):
    return response

